      /* ---------------- Identity Lifecycle ---------------- */
      'connect-hr-source': {
        title: 'Connect an HR source',
        summary: 'Connect your HR system so new hires, transfers and leavers in HR automatically create, update and deactivate users in Fixiam.',
        updated: '2026-09-27', time: '30 minutes', role: 'Super administrator',
        keywords: ['hr', 'hr source', 'sagehr', 'seamlesshr', 'lifecycle', 'onboarding', 'offboarding', 'jml', 'provisioning'],
        accomplish: ['Your HR system connected as an identity source', 'Attribute mappings from HR fields to Fixiam profiles', 'Automatic joiner, mover and leaver processing'],
        prereqs: ['Super administrator role', 'An HR administrator who can generate API credentials', 'A list of the HR fields you want in Fixiam, such as department and manager'],
        steps: [
          { title: 'Choose your HR system', html: `<p>Go to ${ui('Lifecycle')} › ${ui('Identity sources')} and select ${ui('Add source')}. Choose your HR system. Fixiam has built-in connectors for SageHR and SeamlessHR; other systems can connect with <a href="#/guides/configure-inbound-scim">inbound SCIM</a>.</p>`, shot: { area: 'Lifecycle', title: 'Add identity source', path: 'lifecycle/sources/new', kind: 'tiles', items: ['SageHR', 'SeamlessHR', 'Active Directory', 'Google Workspace', 'Inbound SCIM', 'CSV'], mark: 1, caption: 'Built-in HR connectors appear first.' } },
          { title: 'Enter connection details', html: `<p>Enter the API credentials from your HR system. Each connector has its own guide with the exact fields:</p><ul><li><a href="#/guides/configure-sagehr">Configure SageHR</a></li><li><a href="#/guides/configure-seamlesshr">Configure SeamlessHR</a></li></ul>` },
          { title: 'Map attributes', html: `<p>Fixiam suggests mappings for common fields. Review each one, and add mappings for any custom fields.</p>${table(['HR field', 'Fixiam attribute'], [['Work email', '<code>email</code>'], ['Department', '<code>department</code>'], ['Line manager', '<code>manager</code>'], ['Employment status', '<code>status</code>'], ['Termination date', '<code>endDate</code>']], { compact: true })}` },
          { title: 'Set lifecycle rules', html: `<p>Decide what happens for each event:</p><ul><li><strong>Joiner</strong>: create the user and send activation on their start date.</li><li><strong>Mover</strong>: update attributes and recalculate group rules.</li><li><strong>Leaver</strong>: deactivate the user at the end of their last working day.</li></ul>${warn('Run the first sync in preview mode. Fixiam shows what would change without changing anything.')}` },
          { title: 'Run a preview sync', html: `<p>Select ${ui('Preview sync')}. Review the counts of users that would be created, updated and deactivated.</p>` },
          { title: 'Turn on the source', html: `<p>When the preview looks right, select ${ui('Activate')}. Fixiam syncs every 30 minutes by default.</p>` },
        ],
        result: 'The source shows status <strong>Active</strong> and a last sync time. New hires added in HR appear in Fixiam after the next sync.',
        troubleshooting: [
          { q: 'Users are matched to the wrong Fixiam accounts', a: 'Change the matching rule to use employee ID instead of email if emails have been reused.' },
          { q: 'Sync fails with “401 Unauthorized”', a: 'The HR API credentials have expired or were revoked. Generate new credentials in your HR system and update them in Fixiam.' },
        ],
        related: { concepts: ['identity-lifecycle', 'joiner-mover-leaver', 'identity-sources'], guides: ['configure-sagehr', 'configure-seamlesshr', 'configure-inbound-scim', 'deactivate-user'] },
      },
